// Define how Sequelize represents one row from the users table. DataTypes
// describes each column, and the shared Sequelize instance connects this model
// to the configured database.
import { DataTypes } from "sequelize";
import sequelize from "../config/db.js";

// This model describes the existing users table; it does not create or alter
// it. Attribute names match the existing snake_case column names.
const User = sequelize.define(
  "User",
  {
    // Auto-incrementing primary key generated by the database.
    id: {
      type: DataTypes.BIGINT.UNSIGNED,
      primaryKey: true,
      autoIncrement: true,
      allowNull: false,
    },
    // Unique login identifier for each account.
    email: {
      type: DataTypes.STRING(254),
      allowNull: false,
      unique: true,
    },
    // Name shown in the application.
    display_name: {
      type: DataTypes.STRING(80),
      allowNull: false,
    },
    // Only a password hash is stored, never the plaintext password.
    password_hash: {
      type: DataTypes.STRING(255),
      allowNull: false,
    },
    // Defaults match the application's current weekly and monthly targets.
    weekly_workout_goal: {
      type: DataTypes.TINYINT.UNSIGNED,
      allowNull: false,
      defaultValue: 3,
    },
    monthly_workout_goal: {
      type: DataTypes.SMALLINT.UNSIGNED,
      allowNull: false,
      defaultValue: 12,
    },
    // New accounts are active unless explicitly deactivated.
    is_active: {
      type: DataTypes.BOOLEAN,
      allowNull: false,
      defaultValue: true,
    },
    created_at: {
      type: DataTypes.DATE(3),
      allowNull: false,
      defaultValue: DataTypes.NOW,
    },
    updated_at: {
      type: DataTypes.DATE(3),
      allowNull: false,
      defaultValue: DataTypes.NOW,
    },
  },
  {
    // Explicit mapping avoids Sequelize guessing a table name.
    tableName: "users",
    // Sequelize manages timestamps using the table's existing column names.
    timestamps: true,
    createdAt: "created_at",
    updatedAt: "updated_at",
  }
);

export default User;
